import json
d=json.load(open('notes/c_t2.json'))
print(d['scores'], d.get('source_tokens'), d.get('primary_heartbeats'), d.get('accepted_as_best'))
c=d.get('correctness',{})
print(c.get('status'), c.get('primary_passed'))
for e in c.get('errors',[])[:10]: print('ERR:', e[:600])
for v in c.get('versions',[]):
    for e in v.get('errors',[])[:10]: print('VERR:', e[:800])
EOF"

